+			return v.KEVs[i].VulnerabilityName < v.KEVs[j].VulnerabilityName
+		})
+		for i := range v.KEVs {
+			if v.KEVs[i].VulnCheck == nil {
+				continue
+			}
+			sort.Slice(v.KEVs[i].VulnCheck.XDB, func(a, b int) bool {
+				return v.KEVs[i].VulnCheck.XDB[a].XDBID < v.KEVs[i].VulnCheck.XDB[b].XDBID
+			})
+			sort.Slice(v.KEVs[i].VulnCheck.ReportedExploitation, func(a, b int) bool {
+				return v.KEVs[i].VulnCheck.ReportedExploitation[a].URL < v.KEVs[i].VulnCheck.ReportedExploitation[b].URL
+			})
+		}
 		r.ScannedCves[k] = v
 	}
 }
